images.css:
body{background:
 radial-gradient(1100px 650px at 88% 10%, #C9A24A40, transparent 60%),
 radial-gradient(900px 600px at 8% 95%, #8A5A1E55, transparent 60%),
 linear-gradient(160deg,#130E08 0%,#1B140C 55%,#0F0B06 100%) !important;}
.glyph{font-family:'Segoe UI Historic','Noto Sans Egyptian Hieroglyphs',serif}
.k{font-size:20px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:#D9B565}
.gold{color:#D9B565}
.pt{display:flex;gap:14px;align-items:flex-start;font-size:23px;line-height:1.4;opacity:.92}
.pt b{color:#F1D79B}
.pt:before{content:"";flex:none;width:10px;height:10px;margin-top:11px;border-radius:3px;background:linear-gradient(135deg,#E8C778,#A97A2C);transform:rotate(45deg)}
.cap{font-size:18px;opacity:.75;margin-top:12px;text-align:center}
.bsm .bar{height:28px}.bsm .bar i{width:9px;height:9px}.bsm .bar span{height:16px}
.note{font-size:16px;opacity:.55}
.grain:after{display:none}
code{font-family:Consolas,monospace;font-size:.92em;color:#F1D79B}

